/* Pinned synthetic MC68000 vectors, independently generated by MAME.
 * The flat bus deliberately tests CPU behavior independently of console I/O. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "md_native_steps.h"
#include "md_prefetch.h"
static unsigned paid;
void rr_md_cpu_fetch_cycles(unsigned words,int locked) { (void)words;(void)locked;paid=0; }
unsigned rr_md_cpu_stop_cycles(void) { return 4; }
unsigned rr_md_cpu_retire_cycles(unsigned cycles) {
 if(paid>cycles) {fprintf(stderr,"bus budget %u > %u\n",paid,cycles);exit(1);}return cycles-paid;
}
int rr_md_prefetch_active(void) { return 1; }
void rr_md_cpu_bus_lock(int locked) { (void)locked; }
typedef struct { uint32_t address; uint8_t value; } BytePair;
typedef struct { unsigned kind,clock,fc,address,data,uds,lds; } Transaction;
typedef struct {
    const char *name;
    uint32_t initial[19], final[19];
    const BytePair *before; unsigned before_count;
    const BytePair *after; unsigned after_count;
    unsigned cycles;
    const uint16_t *pf_before,*pf_after;
    const Transaction *transactions;unsigned transaction_count,sr_mask;
} CorpusCase;
#include "prefetch_fixture.h"
M68KState g_cpu;
uint8_t g_rom[0x400000], g_ram[0x10000];
static uint8_t flat_bus[0x1000000];
uint64_t g_native_insn_count;
uint32_t g_cycle_accumulator, g_audio_cycle_counter, g_vblank_threshold = 0xffffffffu;
uint32_t rr_md_cpu_stopped;
int g_rte_pending;
static int force_reference;
static unsigned fallback,program_read,tx_count;
static unsigned change_extension;
static Transaction observed[64];
static void tick(unsigned n) {paid+=n;g_audio_cycle_counter+=n;g_cycle_accumulator+=n;}
void rr_md_cpu_idle(unsigned n) {tick(n);}
static void log_tx(unsigned kind,unsigned a,unsigned v,unsigned size) {
 tick(4);unsigned odd=a&1;Transaction t={kind,g_audio_cycle_counter,(g_cpu.SR&SR_S?4:0)+(program_read?2:1),a&0xfffffeu,size==2?v:odd?v:v<<8,size==2||!odd,size==2||odd};
 if(tx_count>=64)abort();observed[tx_count++]=t;
}
int genesis_force_interp(void) { return force_reference; }
void rr_md_cpu_iack(unsigned level) {log_tx('a',0xfffff0u+level*2u,24u+level,2);}
void rr16_note_interpreted(void) { ++fallback; }
void rr16_note_rom_fallback(uint32_t pc) { (void)pc; }
uint32_t rr_md_rom_fetch_offset;
uint32_t rr_md_cart_code_offset(uint32_t pc,const uint16_t *words,unsigned count) { (void)words;(void)count;return pc; }
void rr16_note_ram_instruction(const M68KInstr *ins) { (void)ins; }
void glue_check_vblank(void) {}
int game_instruction_hook_site(uint32_t pc) { (void)pc; return 0; }
int genesis_game_instruction_hook(uint32_t pc) { (void)pc; return 0; }
uint8_t m68k_read8(uint32_t a) {uint8_t v=flat_bus[a&0xffffffu];log_tx('r',a,v,1);return v;}
uint16_t m68k_read16(uint32_t a) {
 a&=0xffffffu;uint16_t v=((unsigned)flat_bus[a]<<8)|flat_bus[(a+1)&0xffffffu];log_tx('r',a,v,2);
 if(change_extension && a==0xff3000) {
  flat_bus[0xff1005]=g_ram[0x1005]=2;change_extension=0;
 }
 return v;
}
uint16_t rr_md_read_instruction_word(uint32_t a) {program_read=1;uint16_t v=m68k_read16(a);program_read=0;return v;}
uint32_t m68k_read32(uint32_t a) {uint32_t hi=m68k_read16(a);uint32_t lo=m68k_read16(a+2);return (hi<<16)|lo;}
void m68k_write8(uint32_t a,uint8_t v) {rr_md_prefetch_before_write();log_tx('w',a,v,1);flat_bus[a&0xffffffu]=v;}
void m68k_write16(uint32_t a,uint16_t v) {rr_md_prefetch_before_write();log_tx('w',a,v,2);flat_bus[a&0xffffffu]=v>>8;flat_bus[(a+1)&0xffffffu]=v;}
void m68k_write32(uint32_t a,uint32_t v) {m68k_write16(a,v>>16);m68k_write16(a+2,v);}
static void fail(const CorpusCase *test, const char *field, uint32_t expected, uint32_t got) {
    fprintf(stderr, "FAIL %s %s %s expected=%08x actual=%08x\n",
            test->name, force_reference ? "reference" : "native", field, expected, got);
    exit(1);
}
static void run_case(const CorpusCase *test) {
    memset(&g_cpu, 0, sizeof g_cpu); memset(flat_bus, 0, sizeof flat_bus);
    memset(g_rom, 0, sizeof g_rom); memset(g_ram, 0, sizeof g_ram);
    memcpy(g_cpu.D, test->initial, sizeof g_cpu.D);
    memcpy(g_cpu.A, test->initial + 8, 7 * sizeof *g_cpu.A);
    g_cpu.SR = (uint16_t)test->initial[17]; g_cpu.PC = test->initial[18];
    g_cpu.A[7] = test->initial[g_cpu.SR & SR_S ? 16 : 15];
    g_cpu.USP = test->initial[g_cpu.SR & SR_S ? 15 : 16];
    for (unsigned i = 0; i < test->before_count; ++i) {
        const BytePair p = test->before[i]; flat_bus[p.address] = p.value;
        if (p.address < sizeof g_rom) g_rom[p.address] = p.value;
    }
    rr_md_prefetch_reset();rr_md_prefetch.pc=g_cpu.PC;rr_md_prefetch.valid=2;
    memcpy(rr_md_prefetch.words,test->pf_before,4);tx_count=0;
    rr_md_cpu_stopped = 0; g_audio_cycle_counter = g_cycle_accumulator = 0;
    g_native_insn_count = 0; fallback = 0;
    M68kiStatus status = m68k_interp_step();
    if (status != M68KI_OK) fail(test, "status", M68KI_OK, status);
    uint32_t actual[19]; memcpy(actual, g_cpu.D, sizeof g_cpu.D);
    memcpy(actual + 8, g_cpu.A, 7 * sizeof *g_cpu.A);
    actual[15] = rr_md_user_sp(); actual[16] = rr_md_supervisor_sp();
    actual[17] = g_cpu.SR; actual[18] = g_cpu.PC;
    for (unsigned i = 0; i < 19; ++i) {
        unsigned mask=i==17?test->sr_mask:0xffffffffu;
        if ((actual[i]&mask) != (test->final[i]&mask)) {
            char field[32]; snprintf(field, sizeof field, "register[%u]", i);
            fail(test, field, test->final[i], actual[i]);
        }
    }
    for (unsigned i = 0; i < test->after_count; ++i) {
        BytePair p = test->after[i];
        if (flat_bus[p.address] != p.value) {
            char field[32]; snprintf(field, sizeof field, "memory[%06x]", p.address);
            fail(test, field, p.value, flat_bus[p.address]);
        }
    }
    if (g_audio_cycle_counter != test->cycles) fail(test, "audio cycles", test->cycles, g_audio_cycle_counter);
    if (g_cycle_accumulator != test->cycles) fail(test, "CPU cycles", test->cycles, g_cycle_accumulator);
    if (rr_md_exception_cycles) fail(test, "unconsumed exception cost", 0, rr_md_exception_cycles);
    if(rr_md_prefetch.valid!=2 || rr_md_prefetch.pc!=g_cpu.PC)fail(test,"queue PC/valid",g_cpu.PC,rr_md_prefetch.pc);
    for(unsigned i=0;i<2;++i)if(rr_md_prefetch.words[i]!=test->pf_after[i])fail(test,"queue word",test->pf_after[i],rr_md_prefetch.words[i]);
    if(tx_count!=test->transaction_count)fail(test,"transaction count",test->transaction_count,tx_count);
    for(unsigned i=0;i<tx_count;++i) {
        const unsigned *a=(const unsigned *)&observed[i],*e=(const unsigned *)&test->transactions[i];
        for(unsigned field=0;field<7;++field)if(field!=2 && a[field]!=e[field]) {
            char name[60];snprintf(name,sizeof name,"bus[%u].field[%u]",i,field);fail(test,name,e[field],a[field]);
        }
    }
    if (fallback != (unsigned)force_reference) fail(test, "interpreted instructions", force_reference, fallback);
}
static void stale_queue(void) {
 memset(&g_cpu,0,sizeof g_cpu);g_cpu.PC=0xff1000;g_cpu.SR=0x2700;
 memset(g_ram,0,sizeof g_ram);g_ram[0x1000]=0x70;g_ram[0x1001]=2;
 flat_bus[0xff1004]=0x4e;flat_bus[0xff1005]=0x71;
 rr_md_prefetch_reset();rr_md_prefetch=(RrMdPrefetch){0xff1000,2,{0x7001,0x4e71}};
 g_audio_cycle_counter=g_cycle_accumulator=rr_md_cpu_stopped=0;tx_count=fallback=0;
 if(m68k_interp_step()!=M68KI_OK || g_cpu.D[0]!=1 || g_cpu.PC!=0xff1002 || fallback!=(unsigned)force_reference)abort();
 /* The instruction itself changes the already-fetched following opcode.
  * Neither path may decode the new RAM bytes for that stale next instruction. */
 const uint8_t code[]={0x33,0xfc,0x70,0x02,0x00,0xff,0x10,0x08,0x70,0x01,0x4e,0x71,0x4e,0x71};
 memcpy(g_ram+0x1000,code,sizeof code);memcpy(flat_bus+0xff1000,code,sizeof code);
 g_cpu.PC=0xff1000;g_cpu.D[0]=0;rr_md_prefetch_reset();
 rr_md_prefetch=(RrMdPrefetch){0xff1000,2,{0x33fc,0x7002}};
 g_audio_cycle_counter=g_cycle_accumulator=0;tx_count=fallback=0;
 if(m68k_interp_step()!=M68KI_OK || g_cpu.PC!=0xff1008 || flat_bus[0xff1009]!=2 ||
    rr_md_prefetch.words[0]!=0x7001 || g_audio_cycle_counter!=20)abort();
 g_ram[0x1009]=flat_bus[0xff1009];
 if(m68k_interp_step()!=M68KI_OK || g_cpu.D[0]!=1 || g_cpu.PC!=0xff100a ||
    fallback!=2u*(unsigned)force_reference || g_audio_cycle_counter!=24)abort();
}
static void exception_phases(void) {
    memset(&g_cpu,0,sizeof g_cpu);memset(flat_bus,0,sizeof flat_bus);
    g_cpu.PC=0xff1000;g_cpu.SR=0xa015;g_cpu.A[7]=0xfff000;
    g_ram[0x1000]=0x4e;g_ram[0x1001]=0x71;
    flat_bus[36]=0;flat_bus[37]=0xff;flat_bus[38]=0x11;flat_bus[39]=0;
    flat_bus[0xff1100]=flat_bus[0xff1102]=0x4e;
    flat_bus[0xff1101]=flat_bus[0xff1103]=0x71;
    rr_md_prefetch_reset();rr_md_prefetch=(RrMdPrefetch){0xff1000,2,{0x4e71,0x4e71}};
    tx_count=fallback=0;g_cycle_accumulator=g_audio_cycle_counter=0;
    if(m68k_interp_step()!=M68KI_OK || g_cpu.PC!=0xff1100 || g_cpu.A[7]!=0xffeffa ||
       g_audio_cycle_counter!=38 || tx_count!=8 || fallback!=(unsigned)force_reference)abort();
    const unsigned trace_clock[]={4,12,16,20,24,28,32,38};
    const unsigned trace_addr[]={0xff1004,0xffeffe,0xffeffa,0xffeffc,36,38,0xff1100,0xff1102};
    for(unsigned n=0;n<8;++n)if(observed[n].clock!=trace_clock[n] || observed[n].address!=trace_addr[n])abort();
    g_cpu.PC=0xff1000;g_cpu.SR=0xa015;g_cpu.A[7]=0xfff000;rr_md_cpu_stopped=1;
    flat_bus[0x78]=0;flat_bus[0x79]=0xff;flat_bus[0x7a]=0x11;flat_bus[0x7b]=0;
    tx_count=0;g_cycle_accumulator=g_audio_cycle_counter=0;
    rr_md_interrupt_entry(6,0x78);
    const unsigned irq_clock[]={10,14,22,26,30,34,38,44};
    const unsigned irq_addr[]={0xffeffe,0xfffffc,0xffeffa,0xffeffc,0x78,0x7a,0xff1100,0xff1102};
    if(tx_count!=8 || g_audio_cycle_counter!=44 || g_cpu.PC!=0xff1100 ||
       g_cpu.SR!=0x2615 || rr_md_cpu_stopped || rr_md_prefetch.valid!=2)abort();
    for(unsigned n=0;n<8;++n)if(observed[n].clock!=irq_clock[n] || observed[n].address!=irq_addr[n])abort();
}
static void changing_move_extension(void) {
    /* The source data access lets another bus master change a destination
     * extension before its actual fetch. Neither path may use its old peek. */
    const uint8_t code[]={0x33,0xd0,0x00,0xff,0x20,0x00,0x4e,0x71,0x4e,0x71};
    memset(flat_bus,0,sizeof flat_bus);memset(g_ram,0,sizeof g_ram);
    memcpy(g_ram+0x1000,code,sizeof code);memcpy(flat_bus+0xff1000,code,sizeof code);
    flat_bus[0xff3000]=0x12;flat_bus[0xff3001]=0x34;
    memset(&g_cpu,0,sizeof g_cpu);g_cpu.PC=0xff1000;g_cpu.A[0]=0xff3000;g_cpu.SR=0x2700;
    rr_md_prefetch_reset();rr_md_prefetch=(RrMdPrefetch){0xff1000,2,{0x33d0,0x00ff}};
    g_audio_cycle_counter=g_cycle_accumulator=rr_md_cpu_stopped=tx_count=fallback=0;change_extension=1;
    if(m68k_interp_step()!=M68KI_OK || flat_bus[0xff2000] ||
       flat_bus[0xff2002]!=0x12 || flat_bus[0xff2003]!=0x34 ||
       g_cpu.PC!=0xff1006 || g_audio_cycle_counter!=20 || fallback!=(unsigned)force_reference)abort();
}
int main(void) {
    unsigned count = sizeof corpus_cases / sizeof *corpus_cases;
    for (force_reference = 0; force_reference <= 1; ++force_reference)
        for (unsigned i = 0; i < count; ++i) run_case(&corpus_cases[i]);
    for(force_reference=0;force_reference<2;++force_reference) {stale_queue();exception_phases();changing_move_extension();}
    printf("{\"corpus_cases\":%u,\"native_checks\":%u,\"reference_checks\":%u,\"stale_ram_and_self_modifying_pipeline\":true,\"authored_trace_and_autovector\":true,\"concurrent_MOVE_extension\":true,\"passed\":true}\n", count, count, count);
    return 0;
}
